// This file is @generated by perseid, vendored from the runtime of the CLI pack.
//! Profiles in `<config dir>/<cli name>/config.toml`, and where each credential comes from.
//! Precedence, per value: flag > environment (`<PREFIX>_API_KEY`, `_BASE_URL`, `_PROFILE`) >
//! the selected profile > the SDK's default; the profile's credential goes through `Auth`.
use std::{
    collections::{BTreeMap, HashMap},
    fmt, fs,
    io::Write,
    path::{Path, PathBuf},
};

use serde::{Deserialize, Serialize};

use super::error::CliError;

/// The profile used when neither `--profile`, `<PREFIX>_PROFILE` nor `default` names one.
pub const DEFAULT_PROFILE: &str = "default";

/// `config.toml`. Unknown keys are kept, so hand edits survive `auth login`.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct ConfigFile {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub default: Option<String>,
    #[serde(flatten)]
    pub extra: toml::Table,
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub profiles: BTreeMap<String, Profile>,
}

#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Profile {
    #[serde(flatten)]
    pub credential: Credential,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub base_url: Option<String>,
}

/// What `auth login` stores in a profile, flat in its table: an API key, OAuth tokens, or the
/// fields of a custom [`Auth`](super::auth::Auth) in `extra`, where unknown keys also land.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct Credential {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub api_key: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub access_token: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub refresh_token: Option<String>,
    /// Unix seconds.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub expires_at: Option<i64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub token_type: Option<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub scopes: Vec<String>,
    /// The login flag that produced it, for [`Methods`](super::auth::Methods) to route refreshes.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub method: Option<String>,
    /// `"keyring"` when `api_key`, `access_token` and `refresh_token` are in the OS keyring
    /// (see `keyring`), not in this file.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub secrets: Option<String>,
    #[serde(flatten)]
    pub extra: toml::Table,
}

impl Credential {
    pub fn api_key(key: impl Into<String>) -> Self {
        Self {
            api_key: Some(key.into()),
            ..Self::default()
        }
    }

    pub fn is_empty(&self) -> bool {
        *self == Self::default()
    }

    /// Whether the access token expires within `margin` seconds of `now`.
    pub fn expires_within(&self, now: i64, margin: i64) -> bool {
        self.expires_at.is_some_and(|at| at <= now + margin)
    }

    /// `api key sk_live_…1234`, `oauth, expires in 12m`, for `auth profiles` and `--debug`,
    /// `in the OS keyring` after them for secrets kept there.
    pub fn describe(&self, now: i64) -> String {
        let described = self.describe_secrets(now);
        match self.secrets.as_deref() {
            Some(super::keyring::KEYRING) => format!("{described}, in the OS keyring"),
            _ => described,
        }
    }

    fn describe_secrets(&self, now: i64) -> String {
        if let Some(key) = &self.api_key {
            return format!("api key {}", mask(key));
        }
        if self.access_token.is_none() {
            return if self.refresh_token.is_some() {
                "oauth, refresh token only".into()
            } else if self.extra.is_empty() {
                "none".into()
            } else {
                "custom".into()
            };
        }
        let refresh = if self.refresh_token.is_some() {
            ", refreshable"
        } else {
            ""
        };
        match self.expires_at {
            None => format!("oauth{refresh}"),
            Some(at) if at <= now => format!("oauth, expired{refresh}"),
            Some(at) => format!("oauth, expires in {}{refresh}", duration(at - now)),
        }
    }
}

fn duration(seconds: i64) -> String {
    match seconds {
        ..60 => format!("{seconds}s"),
        60..3600 => format!("{}m", seconds / 60),
        3600..86_400 => format!("{}h", seconds / 3600),
        _ => format!("{}d", seconds / 86_400),
    }
}

/// Unix seconds.
pub fn now() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |elapsed| {
            i64::try_from(elapsed.as_secs()).unwrap_or(i64::MAX)
        })
}

impl ConfigFile {
    /// Reads the file; a missing file is an empty configuration.
    pub fn load(path: &Path) -> Result<Self, CliError> {
        let text = match fs::read_to_string(path) {
            Ok(text) => text,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                return Ok(Self::default())
            }
            Err(error) => {
                return Err(CliError::config(format!(
                    "cannot read {}: {error}",
                    path.display()
                )))
            }
        };
        toml::from_str(&text)
            .map_err(|error| CliError::config(format!("invalid {}: {error}", path.display())))
    }

    /// Writes the file atomically through a temporary file of its own, readable by its owner only
    /// on unix (0600, directory 0700).
    pub fn save(&self, path: &Path) -> Result<(), CliError> {
        let fail = |error: std::io::Error| {
            CliError::config(format!("cannot write {}: {error}", path.display()))
        };
        let text = toml::to_string(self).map_err(|error| CliError::internal(error.to_string()))?;
        let dir = path.parent().unwrap_or(Path::new("."));
        create_private_dir(dir).map_err(fail)?;
        let name = path.file_name().unwrap_or_default().to_string_lossy();
        let temp = path.with_file_name(format!("{name}.{}.{:x}.tmp", std::process::id(), unique()));
        let mut file = private_options()
            .create_new(true)
            .open(&temp)
            .map_err(fail)?;
        let written = file
            .write_all(text.as_bytes())
            .and_then(|()| file.sync_all());
        drop(file);
        written
            .and_then(|()| fs::rename(&temp, path))
            .map_err(|error| {
                let _ = fs::remove_file(&temp);
                fail(error)
            })
    }

    /// Waits for the exclusive lock of the file at `path`, held by refreshes and `auth` commands
    /// between reading and writing it. `<path>.lock` holds it until the guard drops.
    pub fn lock(path: &Path) -> Result<ConfigLock, CliError> {
        let name = path.file_name().unwrap_or_default().to_string_lossy();
        let lock = path.with_file_name(format!("{name}.lock"));
        let fail = |error: std::io::Error| {
            CliError::config(format!("cannot lock {}: {error}", lock.display()))
        };
        create_private_dir(path.parent().unwrap_or(Path::new("."))).map_err(fail)?;
        let file = private_options()
            .create(true)
            .truncate(false)
            .open(&lock)
            .map_err(fail)?;
        file.lock().map_err(fail)?;
        Ok(ConfigLock(file))
    }

    /// The profile commands use when none is named: `default`, else [`DEFAULT_PROFILE`].
    pub fn default_profile(&self) -> &str {
        self.default.as_deref().unwrap_or(DEFAULT_PROFILE)
    }

    /// Stores the credential (and base URL, when given) in `name`, the default when it is the
    /// first profile. It replaces the previous one, whose unknown keys stay unless it sets them.
    pub fn login(&mut self, name: &str, credential: Credential, base_url: Option<String>) {
        let first = self.profiles.is_empty() && self.default.is_none();
        let profile = self.profiles.entry(name.to_owned()).or_default();
        let mut extra = std::mem::take(&mut profile.credential.extra);
        extra.extend(credential.extra);
        profile.credential = Credential {
            extra,
            ..credential
        };
        if base_url.is_some() {
            profile.base_url = base_url;
        }
        if first {
            self.default = Some(name.to_owned());
        }
    }

    /// Takes the credential of `name`, unknown keys included, and drops the profile once
    /// nothing is left in it. `None` when there was none.
    pub fn logout(&mut self, name: &str) -> Option<Credential> {
        let profile = self.profiles.get_mut(name)?;
        let credential = std::mem::take(&mut profile.credential);
        if profile.base_url.is_none() {
            self.profiles.remove(name);
            if self.default.as_deref() == Some(name) {
                self.default = None;
            }
        }
        Some(credential).filter(|credential| !credential.is_empty())
    }
}

#[cfg(unix)]
fn create_private_dir(dir: &Path) -> std::io::Result<()> {
    use std::os::unix::fs::DirBuilderExt;
    if dir.is_dir() {
        return Ok(());
    }
    fs::DirBuilder::new()
        .recursive(true)
        .mode(0o700)
        .create(dir)
}

#[cfg(not(unix))]
fn create_private_dir(dir: &Path) -> std::io::Result<()> {
    fs::create_dir_all(dir)
}

/// Write access, 0600 on unix.
fn private_options() -> fs::OpenOptions {
    let mut options = fs::OpenOptions::new();
    options.write(true);
    #[cfg(unix)]
    std::os::unix::fs::OpenOptionsExt::mode(&mut options, 0o600);
    options
}

/// Random per process and distinct per call, for temporary file names.
fn unique() -> u64 {
    use std::hash::{BuildHasher, RandomState};
    RandomState::new().hash_one(std::process::id())
}

/// The lock of [`ConfigFile::lock`], released when dropped.
#[derive(Debug)]
pub struct ConfigLock(#[allow(dead_code)] fs::File);

/// `$XDG_CONFIG_HOME` when set (on every platform), else the platform's config directory.
pub fn config_dir(env: &HashMap<String, String>) -> Option<PathBuf> {
    env.get("XDG_CONFIG_HOME")
        .filter(|dir| !dir.is_empty())
        .map(PathBuf::from)
        .or_else(dirs::config_dir)
}

/// `<config dir>/<cli name>/config.toml`.
pub fn config_path(config_dir: &Path, cli_name: &str) -> PathBuf {
    config_dir.join(cli_name).join("config.toml")
}

/// Where a resolved value came from, for `--debug`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Source {
    Flag(&'static str),
    Env(String),
    Profile(String),
    Default,
}

impl fmt::Display for Source {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Flag(flag) => write!(f, "--{flag}"),
            Self::Env(name) => write!(f, "${name}"),
            Self::Profile(name) => write!(f, "profile `{name}`"),
            Self::Default => f.write_str("default"),
        }
    }
}

/// The values the command line gives, which win over everything else.
#[derive(Clone, Copy, Debug, Default)]
pub struct Overrides<'a> {
    pub profile: Option<&'a str>,
    pub api_key: Option<&'a str>,
    pub base_url: Option<&'a str>,
}

/// The credentials a command runs with.
#[derive(Clone, Debug, PartialEq)]
pub struct Credentials {
    pub profile: String,
    pub profile_source: Source,
    /// `--api-key` or `<PREFIX>_API_KEY`, which win over the profile's credential.
    pub api_key: Option<String>,
    pub api_key_source: Source,
    /// What the profile stores, handed to the [`Auth`](super::auth::Auth) hook.
    pub credential: Credential,
    /// `None` leaves the SDK's default base URL.
    pub base_url: Option<String>,
    pub base_url_source: Source,
}

/// Applies the precedence. A profile named by flag or environment must exist.
pub fn resolve(
    file: &ConfigFile,
    flags: Overrides<'_>,
    env: &HashMap<String, String>,
    env_prefix: &str,
) -> Result<Credentials, CliError> {
    let credentials = resolve_lenient(file, flags, env, env_prefix);
    if credentials.profile_source != Source::Default
        && !file.profiles.contains_key(&credentials.profile)
    {
        let (profile, source) = (&credentials.profile, &credentials.profile_source);
        return Err(CliError::config(format!(
            "no profile `{profile}` (from {source}); create it with `auth login --profile {profile}`"
        )));
    }
    Ok(credentials)
}

/// [`resolve`] for `auth` commands, where the profile need not exist yet.
pub fn resolve_lenient(
    file: &ConfigFile,
    flags: Overrides<'_>,
    env: &HashMap<String, String>,
    env_prefix: &str,
) -> Credentials {
    let var = |suffix: &str| {
        let name = format!("{env_prefix}_{suffix}");
        let value = env.get(&name).filter(|value| !value.is_empty()).cloned();
        value.map(|value| (value, Source::Env(name)))
    };
    let flag = |value: Option<&str>, name: &'static str| {
        value.map(|value| (value.to_owned(), Source::Flag(name)))
    };

    let (profile, profile_source) = flag(flags.profile, "profile")
        .or_else(|| var("PROFILE"))
        .unwrap_or_else(|| (file.default_profile().to_owned(), Source::Default));
    let stored = file.profiles.get(&profile);
    let (api_key, api_key_source) =
        split(flag(flags.api_key, "api-key").or_else(|| var("API_KEY")));
    let (base_url, base_url_source) = split(
        flag(flags.base_url, "base-url")
            .or_else(|| var("BASE_URL"))
            .or_else(|| {
                let url = stored.and_then(|p| p.base_url.clone())?;
                Some((url, Source::Profile(profile.clone())))
            }),
    );
    Credentials {
        credential: stored.map(|p| p.credential.clone()).unwrap_or_default(),
        profile,
        profile_source,
        api_key,
        api_key_source,
        base_url,
        base_url_source,
    }
}

fn split(value: Option<(String, Source)>) -> (Option<String>, Source) {
    match value {
        Some((value, source)) => (Some(value), source),
        None => (None, Source::Default),
    }
}

/// `sk_live_…1234`: enough to tell keys apart, never the key.
pub fn mask(secret: &str) -> String {
    let chars: Vec<char> = secret.chars().collect();
    if chars.len() <= 8 {
        return "…".repeat(usize::from(!chars.is_empty()));
    }
    let prefix: String = match secret.rfind('_') {
        Some(end) if end < 12 && end + 5 < secret.len() => secret[..=end].to_owned(),
        _ => String::new(),
    };
    let suffix: String = chars[chars.len() - 4..].iter().collect();
    format!("{prefix}…{suffix}")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn env(vars: &[(&str, &str)]) -> HashMap<String, String> {
        vars.iter()
            .map(|(k, v)| ((*k).to_owned(), (*v).to_owned()))
            .collect()
    }

    fn file() -> ConfigFile {
        toml::from_str(
            r#"
            default = "prod"
            [profiles.prod]
            api_key = "sk_prod"
            [profiles.staging]
            api_key = "sk_staging"
            base_url = "https://staging.acme.dev"
            "#,
        )
        .unwrap()
    }

    #[test]
    fn the_default_profile_applies_without_flags_or_env() {
        let creds = resolve(&file(), Overrides::default(), &env(&[]), "ACME").unwrap();
        assert_eq!(creds.profile, "prod");
        assert_eq!(creds.api_key, None);
        assert_eq!(creds.credential, Credential::api_key("sk_prod"));
        assert_eq!(creds.base_url, None);
        assert_eq!(creds.base_url_source, Source::Default);
    }

    #[test]
    fn env_beats_the_profile_and_flags_beat_env() {
        let vars = env(&[("ACME_PROFILE", "staging"), ("ACME_API_KEY", "sk_env")]);
        let creds = resolve(&file(), Overrides::default(), &vars, "ACME").unwrap();
        assert_eq!(creds.profile, "staging");
        assert_eq!(creds.api_key.as_deref(), Some("sk_env"));
        assert_eq!(creds.api_key_source.to_string(), "$ACME_API_KEY");
        assert_eq!(creds.base_url.as_deref(), Some("https://staging.acme.dev"));

        let flags = Overrides {
            profile: Some("prod"),
            api_key: Some("sk_flag"),
            base_url: Some("http://localhost:8080"),
        };
        let creds = resolve(&file(), flags, &vars, "ACME").unwrap();
        assert_eq!(creds.profile, "prod");
        assert_eq!(creds.api_key.as_deref(), Some("sk_flag"));
        assert_eq!(creds.base_url.as_deref(), Some("http://localhost:8080"));
        assert_eq!(creds.base_url_source.to_string(), "--base-url");
    }

    #[test]
    fn empty_env_values_are_unset() {
        let creds = resolve(
            &file(),
            Overrides::default(),
            &env(&[("ACME_API_KEY", "")]),
            "ACME",
        )
        .unwrap();
        assert_eq!(creds.api_key, None);
        assert_eq!(creds.api_key_source, Source::Default);
        assert_eq!(creds.credential.api_key.as_deref(), Some("sk_prod"));
    }

    #[test]
    fn an_explicit_unknown_profile_is_an_error_an_implicit_one_is_empty() {
        let flags = Overrides {
            profile: Some("nope"),
            ..Overrides::default()
        };
        let error = resolve(&file(), flags, &env(&[]), "ACME").unwrap_err();
        assert_eq!(error.exit_code(), super::super::error::exit::CONFIG);
        assert!(
            error
                .message()
                .contains("no profile `nope` (from --profile)"),
            "{error}"
        );

        let creds = resolve(
            &ConfigFile::default(),
            Overrides::default(),
            &env(&[]),
            "ACME",
        )
        .unwrap();
        assert_eq!(creds.profile, DEFAULT_PROFILE);
        assert!(creds.credential.is_empty());
        let lenient = resolve_lenient(&file(), flags, &env(&[]), "ACME");
        assert_eq!(lenient.profile, "nope");
    }

    #[test]
    fn save_and_load_round_trip_with_owner_only_permissions() {
        let dir = tempfile::tempdir().unwrap();
        let path = config_path(dir.path(), "acme");
        assert_eq!(ConfigFile::load(&path).unwrap(), ConfigFile::default());

        let mut config = ConfigFile::default();
        config.login(
            "prod",
            Credential::api_key("sk_1"),
            Some("https://api.acme.dev".into()),
        );
        config.login("staging", Credential::api_key("sk_2"), None);
        config.save(&path).unwrap();
        assert_eq!(ConfigFile::load(&path).unwrap(), config);
        assert_eq!(
            fs::read_to_string(&path).unwrap(),
            "default = \"prod\"\n\n[profiles.prod]\napi_key = \"sk_1\"\nbase_url = \"https://api.acme.dev\"\n\n[profiles.staging]\napi_key = \"sk_2\"\n"
        );

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = |p: &Path| fs::metadata(p).unwrap().permissions().mode() & 0o777;
            assert_eq!(mode(&path), 0o600);
            assert_eq!(mode(path.parent().unwrap()), 0o700);
            fs::set_permissions(&path, fs::Permissions::from_mode(0o644)).unwrap();
            config.save(&path).unwrap();
            assert_eq!(mode(&path), 0o600);
        }
    }

    #[test]
    fn only_the_first_profile_becomes_the_default() {
        let mut config: ConfigFile =
            toml::from_str("[profiles.default]\napi_key = \"sk\"\n").unwrap();
        config.login("staging", Credential::api_key("sk_2"), None);
        assert_eq!(config.default, None);
        assert_eq!(config.default_profile(), DEFAULT_PROFILE);

        let mut empty = ConfigFile::default();
        empty.login("staging", Credential::api_key("sk_2"), None);
        empty.login("prod", Credential::api_key("sk_3"), None);
        assert_eq!(empty.default.as_deref(), Some("staging"));
    }

    /// Windows may refuse to replace a file another replacement is deleting: saves of the
    /// runtime are serialized by [`ConfigFile::lock`].
    #[cfg(unix)]
    #[test]
    fn concurrent_saves_leave_a_whole_file_and_no_temporary_one() {
        let dir = tempfile::tempdir().unwrap();
        let path = config_path(dir.path(), "acme");
        let writers: Vec<_> = (0..8)
            .map(|i| {
                let path = path.clone();
                std::thread::spawn(move || {
                    let mut config = ConfigFile::default();
                    config.login("prod", Credential::api_key(format!("sk_{i}")), None);
                    config.save(&path).unwrap();
                })
            })
            .collect();
        for writer in writers {
            writer.join().unwrap();
        }
        assert!(ConfigFile::load(&path).unwrap().profiles["prod"]
            .credential
            .api_key
            .is_some());
        let names: Vec<_> = fs::read_dir(path.parent().unwrap())
            .unwrap()
            .map(|entry| entry.unwrap().file_name())
            .collect();
        assert_eq!(names, ["config.toml"]);
    }

    #[test]
    fn the_lock_is_exclusive_until_dropped() {
        let dir = tempfile::tempdir().unwrap();
        let path = config_path(dir.path(), "acme");
        let held = ConfigFile::lock(&path).unwrap();
        let (sender, receiver) = std::sync::mpsc::channel();
        let waiter = std::thread::spawn(move || {
            let _lock = ConfigFile::lock(&path).unwrap();
            sender.send(()).unwrap();
        });
        let wait = std::time::Duration::from_millis(200);
        assert!(receiver.recv_timeout(wait).is_err());
        drop(held);
        receiver.recv_timeout(wait * 10).unwrap();
        waiter.join().unwrap();
    }

    #[test]
    fn unknown_keys_survive_a_rewrite() {
        let mut config: ConfigFile =
            toml::from_str("editor = \"vim\"\n[profiles.prod]\napi_key = \"sk\"\norg = \"acme\"\n")
                .unwrap();
        config.login("prod", Credential::api_key("sk_new"), None);
        let text = toml::to_string(&config).unwrap();
        assert!(text.contains("editor = \"vim\""), "{text}");
        assert!(text.contains("org = \"acme\""), "{text}");
        assert!(text.contains("api_key = \"sk_new\""), "{text}");
    }

    #[test]
    fn logout_drops_the_credential_then_the_empty_profile() {
        let mut config = file();
        assert_eq!(
            config.logout("staging"),
            Some(Credential::api_key("sk_staging"))
        );
        assert_eq!(
            config.profiles["staging"].base_url.as_deref(),
            Some("https://staging.acme.dev")
        );
        assert_eq!(config.logout("staging"), None);
        assert!(config.logout("prod").is_some());
        assert!(!config.profiles.contains_key("prod"));
        assert_eq!(config.default, None);
        assert_eq!(config.logout("prod"), None);
    }

    #[test]
    fn oauth_and_custom_credentials_round_trip() {
        let text = "[profiles.prod]\naccess_token = \"at_1\"\nrefresh_token = \"rt_1\"\nexpires_at = 1700000000\ntoken_type = \"Bearer\"\nscopes = [\"read\", \"write\"]\nmethod = \"web\"\norg = \"acme\"\nbase_url = \"https://api.acme.dev\"\n\n[profiles.prod.session]\nid = 7\n";
        let config: ConfigFile = toml::from_str(text).unwrap();
        let prod = &config.profiles["prod"];
        assert_eq!(prod.credential.access_token.as_deref(), Some("at_1"));
        assert_eq!(prod.credential.expires_at, Some(1_700_000_000));
        assert_eq!(prod.credential.scopes, ["read", "write"]);
        assert_eq!(prod.credential.extra["org"].as_str(), Some("acme"));
        assert_eq!(prod.base_url.as_deref(), Some("https://api.acme.dev"));
        assert_eq!(toml::to_string(&config).unwrap(), text);

        let mut config = config;
        config.login("prod", Credential::api_key("sk_1"), None);
        let prod = &config.profiles["prod"].credential;
        assert_eq!(prod.access_token, None);
        assert_eq!(prod.refresh_token, None);
        assert_eq!(prod.method, None);
        assert_eq!(prod.extra["org"].as_str(), Some("acme"));
    }

    #[test]
    fn credentials_describe_themselves() {
        let oauth = |expires_at, refresh: Option<&str>| Credential {
            access_token: Some("at".into()),
            refresh_token: refresh.map(Into::into),
            expires_at,
            ..Credential::default()
        };
        assert_eq!(
            Credential::api_key("sk_live_abcdefgh1234").describe(0),
            "api key sk_live_…1234"
        );
        assert_eq!(
            oauth(Some(1000 + 720), None).describe(1000),
            "oauth, expires in 12m"
        );
        assert_eq!(
            oauth(Some(1000), Some("rt")).describe(1000),
            "oauth, expired, refreshable"
        );
        assert_eq!(oauth(None, None).describe(0), "oauth");
        assert_eq!(Credential::default().describe(0), "none");
        assert!(oauth(Some(1030), None).expires_within(1000, 60));
        assert!(!oauth(None, None).expires_within(1000, 60));
    }

    #[test]
    fn invalid_files_are_config_errors() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("config.toml");
        fs::write(&path, "profiles = 3").unwrap();
        let error = ConfigFile::load(&path).unwrap_err();
        assert_eq!(error.exit_code(), super::super::error::exit::CONFIG);
    }

    #[test]
    fn masks_keep_the_prefix_and_the_last_four_characters() {
        assert_eq!(mask("sk_live_abcdefgh1234"), "sk_live_…1234");
        assert_eq!(mask("abcdefghijklmnop"), "…mnop");
        assert_eq!(mask("short"), "…");
        assert_eq!(mask(""), "");
    }
}
